export const getAzkarAudioSource = (filename: string | null | undefined): any | null => {
  if (!filename) return null;
  // Support both old .mp3 keys and new .m4a keys for backwards compatibility
  const m4aKey = filename.replace(/\.mp3$/, ".m4a");
  return AZKAR_AUDIO_MAP[m4aKey] || AZKAR_AUDIO_MAP[filename] || null;
};
